// Count Me In. Generated by Event Book from "Count me in · plan": don't edit it, generating again overwrites it.
// Pending while ./count-me-in.slice.mjs throws NotBuiltYet; run it red with GWT_RUN_PENDING=1.
import { chapter, scenario } from "@jocelynenglund/itsybit-gwt";
import { countMeIn } from "./count-me-in.slice.mjs";

chapter("Show interest", () => {
  scenario("Counting yourself in")
    .given(["InterestCheckStarted", { "checkId": "c1", "title": "Board games", "goal": 10 }])
    .when("Count Me In", { "checkId": "c1", "personId": "p1", "name": "Ana", "on": "2026-11-04" }, countMeIn)
    .then(["InterestShown", { "checkId": "c1", "personId": "p1", "name": "Ana" }]);

  scenario("You need a name")
    .given(["InterestCheckStarted", { "checkId": "c1", "title": "Board games", "goal": 10 }])
    .when("Count Me In", { "checkId": "c1", "personId": "p1", "name": "" }, countMeIn)
    .thenNothing("What's your name?");

  scenario("Counting in twice is refused")
    .given(["InterestCheckStarted", { "checkId": "c1", "title": "Board games", "goal": 10 }], ["InterestShown", { "checkId": "c1", "personId": "p1", "name": "Ana" }])
    .when("Count Me In", { "checkId": "c1", "personId": "p1", "name": "Ana" }, countMeIn)
    .thenNothing("You're already counted in");

  scenario("Changed your mind, then back in")
    .given(["InterestCheckStarted", { "checkId": "c1", "title": "Board games", "goal": 10 }], ["InterestShown", { "checkId": "c1", "personId": "p1", "name": "Ana" }], ["InterestWithdrawn", { "checkId": "c1", "personId": "p1" }])
    .when("Count Me In", { "checkId": "c1", "personId": "p1", "name": "Ana" }, countMeIn)
    .then(["InterestShown", { "personId": "p1" }]);

  scenario("A closed check takes no more interest")
    .given(["InterestCheckStarted", { "checkId": "c1", "title": "Board games", "goal": 10 }], ["InterestCheckClosed", { "checkId": "c1" }])
    .when("Count Me In", { "checkId": "c1", "personId": "p2", "name": "Ben" }, countMeIn)
    .thenNothing("This interest check has closed");

  scenario("No such interest check")
    .when("Count Me In", { "checkId": "c9", "personId": "p1", "name": "Ana" }, countMeIn)
    .thenNothing("No such interest check");
});
